void ktetra(int iopt, int jtype, std::vector<double>& ecpt, Eigen::MatrixXd& stiffness_matrix,
            double E, double nu, const std::vector<std::vector<double>>& node_coords) {
    // Build H matrix (4x4) from nodal coordinates
    Eigen::Matrix4d H;
    H.setZero();
    H(0,0) = 1.0; H(0,1) = ecpt[7]; H(0,2) = ecpt[8]; H(0,3) = ecpt[9];   // Node 1
    H(1,0) = 1.0; H(1,1) = ecpt[11]; H(1,2) = ecpt[12]; H(1,3) = ecpt[13]; // Node 2
    H(2,0) = 1.0; H(2,1) = ecpt[15]; H(2,2) = ecpt[16]; H(2,3) = ecpt[17]; // Node 3
    H(3,0) = 1.0; H(3,1) = ecpt[19]; H(3,2) = ecpt[20]; H(3,3) = ecpt[21]; // Node 4

    // Invert H to get shape function gradients
    Eigen::Matrix4d H_inv;
    double h_deter;
    if (!invert4x4(H, H_inv, h_deter)) {
        return;
    }
    h_deter = std::abs(h_deter);

    // Compute material matrix G
    Matrix6d G = computeG(E, nu);

    // Compute C matrices using H_inv (gradients)
    std::vector<Eigen::Matrix<double,6,3>> C = computeC(H_inv);

    // Scaling factor: for linear tet, K = (|J| / 6) * sum_{i,j} B_i^T D B_j, and |J| = |det(H)| / 6
    // So total scale = |det(H)| / 36.0. Wedge first 6 tets are doubled in weight.
    double scale_factor = h_deter / 36.0;
    if (jtype == 1 && iopt <= 6) {
        scale_factor *= 2.0;
    }

    // Precompute T (identity)
    Eigen::Matrix3d T = computeT();

    // Loop over all node pairs (i,j) in tet: 4 nodes → 12 DOF → 12x12 local K
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            // Compute local 3x3 K_ij = C[i]^T * G * C[j]
            Eigen::Matrix<double,3,6> CT_i;
            CT_i.setZero();
            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 6; ++c) {
                    CT_i(r,c) = C[i](c,r);
                }
            }
            Eigen::Matrix3d KIJ_local = CT_i * G * C[j];

            // Apply scaling
            KIJ_local *= scale_factor;

            // Map node IDs to global DOF indices
            int node_i_id = static_cast<int>(ecpt[2+i]);
            int node_j_id = static_cast<int>(ecpt[2+j]);
            int dof_i_start = 3 * (node_i_id - 1);
            int dof_j_start = 3 * (node_j_id - 1);

            // Add to global stiffness matrix
            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    stiffness_matrix(dof_i_start + r, dof_j_start + c) += KIJ_local(r,c);
                }
            }
        }
    }
